15	/// RequestTemplate is an extension of a Mustache template.
16	/// Various parts of the template can be written as a mustache template.
17	/// When `to_request` is called, all mustache templates are evaluated.
18	/// To call `to_request` we need to provide a context.
19	#[derive(Setters, Debug, Clone)]
20	pub struct RequestTemplate {
21	    pub root_url: Mustache,
22	    pub query: Vec<(String, Mustache)>,
23	    pub method: reqwest::Method,
24	    pub headers: MustacheHeaders,
25	    pub body_path: Option<Mustache>,
26	    pub endpoint: Endpoint,
27	    pub encoding: Encoding,
28	}
29	
30	impl RequestTemplate {
31	    /// Creates a URL for the context
32	    /// Fills in all the mustache templates with required values.
33	    fn create_url<C: PathString>(&self, ctx: &C) -> anyhow::Result<Url> {
34	        let mut url = url::Url::parse(self.root_url.render(ctx).as_str())?;
35	        if self.query.is_empty() && self.root_url.is_const() {
36	            return Ok(url);
37	        }
38	        let extra_qp = self.query.iter().filter_map(|(k, v)| {
39	            let value = v.render(ctx);
40	            if value.is_empty() {
41	                None
42	            } else {
43	                Some((Cow::Borrowed(k.as_str()), Cow::Owned(value)))
44	            }
45	        });
46	
47	        let base_qp = url
48	            .query_pairs()
49	            .filter_map(|(k, v)| if v.is_empty() { None } else { Some((k, v)) });
50	
51	        let qp_string = base_qp
52	            .chain(extra_qp)
53	            .map(|(k, v)| format!("{}={}", k, v))
54	            .fold("".to_string(), |str, item| {
55	                if str.is_empty() {
56	                    item
57	                } else {
58	                    format!("{}&{}", str, item)
59	                }
60	            });
61	
62	        if qp_string.is_empty() {
63	            url.set_query(None);
64	            Ok(url)
65	        } else {
66	            url.set_query(Some(qp_string.as_str()));
67	            Ok(url)
68	        }
69	    }
70	
71	    /// Checks if the template has any mustache templates or not
72	    /// Returns true if there are not templates
73	    pub fn is_const(&self) -> bool {
74	        self.root_url.is_const()
75	            && self.body_path.as_ref().map_or(true, Mustache::is_const)
76	            && self.query.iter().all(|(_, v)| v.is_const())
77	            && self.headers.iter().all(|(_, v)| v.is_const())
78	    }
79	
80	    /// Creates a HeaderMap for the context
81	    fn create_headers<C: PathString>(&self, ctx: &C) -> HeaderMap {
82	        let mut header_map = HeaderMap::new();
83	
84	        for (k, v) in &self.headers {
85	            if let Ok(header_value) = HeaderValue::from_str(&v.render(ctx)) {
86	                header_map.insert(k, header_value);
87	            }
88	        }
89	
90	        header_map
91	    }
92	
93	    /// Creates a Request for the given context
94	    pub fn to_request<C: PathString + HasHeaders>(
95	        &self,
96	        ctx: &C,
97	    ) -> anyhow::Result<reqwest::Request> {
98	        // Create url
99	        let url = self.create_url(ctx)?;
100	        let method = self.method.clone();
101	        let mut req = reqwest::Request::new(method, url);
102	        req = self.set_headers(req, ctx);
103	        req = self.set_body(req, ctx)?;
104	
105	        Ok(req)
106	    }
107	
108	    /// Sets the body for the request
109	    fn set_body<C: PathString + HasHeaders>(
110	        &self,
111	        mut req: reqwest::Request,
112	        ctx: &C,
113	    ) -> anyhow::Result<reqwest::Request> {
114	        if let Some(body_path) = &self.body_path {
115	            match &self.encoding {
116	                Encoding::ApplicationJson => {
117	                    req.body_mut().replace(body_path.render(ctx).into());
118	                }
119	                Encoding::ApplicationXWwwFormUrlencoded => {
120	                    // TODO: this is a performance bottleneck
121	                    // We first encode everything to string and then back to form-urlencoded
122	                    let body: String = body_path.render(ctx);
123	                    let form_data = match serde_json::from_str::<serde_json::Value>(&body) {
124	                        Ok(deserialized_data) => serde_urlencoded::to_string(deserialized_data)?,
125	                        Err(_) => body,
126	                    };
127	
128	                    req.body_mut().replace(form_data.into());
129	                }
130	            }
131	        }
132	        Ok(req)
133	    }
134	
135	    /// Sets the headers for the request
136	    fn set_headers<C: PathString + HasHeaders>(
137	        &self,
138	        mut req: reqwest::Request,
139	        ctx: &C,
140	    ) -> reqwest::Request {
141	        let headers = self.create_headers(ctx);
142	        if !headers.is_empty() {
143	            req.headers_mut().extend(headers);
144	        }
145	
146	        let headers = req.headers_mut();
147	        // We want to set the header value based on encoding
148	        // TODO: potential of optimizations.
149	        // Can set content-type headers while creating the request template
150	        if self.method != reqwest::Method::GET {
151	            headers.insert(
152	                reqwest::header::CONTENT_TYPE,
153	                match self.encoding {
154	                    Encoding::ApplicationJson => HeaderValue::from_static("application/json"),
155	                    Encoding::ApplicationXWwwFormUrlencoded => {
156	                        HeaderValue::from_static("application/x-www-form-urlencoded")
157	                    }
158	                },
159	            );
160	        }
161	
162	        headers.extend(ctx.headers().to_owned());
163	        req
164	    }
165	
166	    pub fn new(root_url: &str) -> anyhow::Result<Self> {
167	        Ok(Self {
168	            root_url: Mustache::parse(root_url)?,
169	            query: Default::default(),
170	            method: reqwest::Method::GET,
171	            headers: Default::default(),
172	            body_path: Default::default(),
173	            endpoint: Endpoint::new(root_url.to_string()),
174	            encoding: Default::default(),
175	        })
176	    }
177	
178	    pub fn form_encoded_url(url: &str) -> anyhow::Result<Self> {
179	        Ok(Self::new(url)?.encoding(Encoding::ApplicationXWwwFormUrlencoded))
180	    }
181	}
