183	impl TryFrom<Endpoint> for RequestTemplate {
184	    type Error = anyhow::Error;
185	    fn try_from(endpoint: Endpoint) -> anyhow::Result<Self> {
186	        let path = Mustache::parse(endpoint.path.as_str())?;
187	        let query = endpoint
188	            .query
189	            .iter()
190	            .map(|(k, v)| Ok((k.to_owned(), Mustache::parse(v.as_str())?)))
191	            .collect::<anyhow::Result<Vec<_>>>()?;
192	        let method = endpoint.method.clone().to_hyper();
193	        let headers = endpoint
194	            .headers
195	            .iter()
196	            .map(|(k, v)| Ok((k.clone(), Mustache::parse(v.to_str()?)?)))
197	            .collect::<anyhow::Result<Vec<_>>>()?;
198	
199	        let body = if let Some(body) = &endpoint.body {
200	            Some(Mustache::parse(body.as_str())?)
201	        } else {
202	            None
203	        };
204	        let encoding = endpoint.encoding.clone();
205	
206	        Ok(Self {
207	            root_url: path,
208	            query,
209	            method,
210	            headers,
211	            body_path: body,
212	            endpoint,
213	            encoding,
214	        })
215	    }
216	}
