26	impl RequestTemplate {
27	    fn create_headers<C: PathGraphql>(&self, ctx: &C) -> HeaderMap {
28	        let mut header_map = HeaderMap::new();
29	
30	        for (k, v) in &self.headers {
31	            if let Ok(header_value) = HeaderValue::from_str(&v.render_graphql(ctx)) {
32	                header_map.insert(k, header_value);
33	            }
34	        }
35	
36	        header_map
37	    }
38	
39	    fn set_headers<C: PathGraphql + HasHeaders>(
40	        &self,
41	        mut req: reqwest::Request,
42	        ctx: &C,
43	    ) -> reqwest::Request {
44	        let headers = req.headers_mut();
45	        let config_headers = self.create_headers(ctx);
46	
47	        if !config_headers.is_empty() {
48	            headers.extend(config_headers);
49	        }
50	        headers.insert(
51	            reqwest::header::CONTENT_TYPE,
52	            HeaderValue::from_static("application/json"),
53	        );
54	        headers.extend(ctx.headers().to_owned());
55	        req
56	    }
57	
58	    pub fn to_request<C: PathGraphql + HasHeaders + GraphQLOperationContext>(
59	        &self,
60	        ctx: &C,
61	    ) -> anyhow::Result<reqwest::Request> {
62	        let mut req = reqwest::Request::new(POST.to_hyper(), url::Url::parse(self.url.as_str())?);
63	        req = self.set_headers(req, ctx);
64	        req = self.set_body(req, ctx);
65	        Ok(req)
66	    }
67	
68	    fn set_body<C: PathGraphql + HasHeaders + GraphQLOperationContext>(
69	        &self,
70	        mut req: reqwest::Request,
71	        ctx: &C,
72	    ) -> reqwest::Request {
73	        let operation_type = &self.operation_type;
74	        let selection_set = ctx.selection_set().unwrap_or_default();
75	        let operation = self
76	            .operation_arguments
77	            .as_ref()
78	            .map(|args| {
79	                args.iter()
80	                    .map(|(k, v)| format!(r#"{}: {}"#, k, v.render_graphql(ctx).escape_default()))
81	                    .collect::<Vec<_>>()
82	                    .join(", ")
83	            })
84	            .map(|args| format!("{}({})", self.operation_name, args))
85	            .unwrap_or(self.operation_name.clone());
86	
87	        let graphql_query =
88	            format!(r#"{{ "query": "{operation_type} {{ {operation} {selection_set} }}" }}"#);
89	
90	        req.body_mut().replace(graphql_query.into());
91	        req
92	    }
93	
94	    pub fn new(
95	        url: String,
96	        operation_type: &GraphQLOperationType,
97	        operation_name: &str,
98	        args: Option<&KeyValues>,
99	        headers: MustacheHeaders,
100	    ) -> anyhow::Result<Self> {
101	        let mut operation_arguments = None;
102	
103	        if let Some(args) = args.as_ref() {
104	            operation_arguments = Some(
105	                args.iter()
106	                    .map(|(k, v)| Ok((k.to_owned(), Mustache::parse(v)?)))
107	                    .collect::<anyhow::Result<Vec<_>>>()?,
108	            );
109	        }
110	
111	        Ok(Self {
112	            url,
113	            operation_type: operation_type.to_owned(),
114	            operation_name: operation_name.to_owned(),
115	            operation_arguments,
116	            headers,
117	        })
118	    }
119	}
